using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using SquashClub.Web.Domain;

namespace SquashClub.Web.Data;
public sealed class ClubDbContext(DbContextOptions<ClubDbContext> options) : IdentityDbContext<Member, Microsoft.AspNetCore.Identity.IdentityRole<Guid>, Guid>(options)
{
 public DbSet<Membership> Memberships=>Set<Membership>(); public DbSet<MembershipProduct> MembershipProducts=>Set<MembershipProduct>(); public DbSet<Court> Courts=>Set<Court>(); public DbSet<OpeningHour> OpeningHours=>Set<OpeningHour>(); public DbSet<PeakPeriod> PeakPeriods=>Set<PeakPeriod>(); public DbSet<CourtClosure> CourtClosures=>Set<CourtClosure>(); public DbSet<Booking> Bookings=>Set<Booking>(); public DbSet<BookingPaymentShare> BookingPaymentShares=>Set<BookingPaymentShare>(); public DbSet<CreditTransaction> CreditTransactions=>Set<CreditTransaction>(); public DbSet<CreditPackage> CreditPackages=>Set<CreditPackage>(); public DbSet<CancellationSubscription> CancellationSubscriptions=>Set<CancellationSubscription>(); public DbSet<LightingDevice> LightingDevices=>Set<LightingDevice>(); public DbSet<CourtLightingSession> LightingSessions=>Set<CourtLightingSession>(); public DbSet<Ladder> Ladders=>Set<Ladder>(); public DbSet<LadderParticipant> LadderParticipants=>Set<LadderParticipant>(); public DbSet<AuditLog> AuditLogs=>Set<AuditLog>(); public DbSet<SystemSetting> SystemSettings=>Set<SystemSetting>();
 public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<PaymentWebhookEvent> PaymentWebhookEvents=>Set<PaymentWebhookEvent>(); public DbSet<BookingCancellation> BookingCancellations=>Set<BookingCancellation>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<LadderChallenge> LadderChallenges=>Set<LadderChallenge>(); public DbSet<LadderMatch> LadderMatches=>Set<LadderMatch>(); public DbSet<LadderRankingHistory> LadderRankingHistory=>Set<LadderRankingHistory>(); public DbSet<ExternalApiClient> ExternalApiClients=>Set<ExternalApiClient>();
 protected override void OnModelCreating(ModelBuilder b) { base.OnModelCreating(b); b.Entity<Member>().Property(x=>x.Version).IsRowVersion(); b.Entity<Booking>().HasIndex(x=>new{x.CourtId,x.StartsAtUtc}).IsUnique().HasFilter("\"Status\" = 0"); b.Entity<CreditTransaction>().HasIndex(x=>x.ExternalReference).IsUnique().HasFilter("\"ExternalReference\" IS NOT NULL"); b.Entity<BookingPaymentShare>().HasIndex(x=>new{x.BookingId,x.MemberId}).IsUnique(); b.Entity<CourtLightingSession>().HasIndex(x=>x.BookingId).IsUnique().HasFilter("\"Status\" IN (0, 1)"); b.Entity<LadderParticipant>().HasIndex(x=>new{x.LadderId,x.Rank}).IsUnique(); b.Entity<Payment>().HasIndex(x=>x.ProviderPaymentId).IsUnique(); b.Entity<PaymentWebhookEvent>().HasIndex(x=>new{x.Provider,x.ProviderEventId}).IsUnique(); b.Entity<LadderMatch>().HasIndex(x=>x.ChallengeId).IsUnique(); b.Entity<ExternalApiClient>().HasIndex(x=>x.KeyId).IsUnique(); b.Entity<SystemSetting>().HasKey(x=>x.Key); }
}
